def dijkstra_shortest_path_costs(n_nodes: int, adj_list: list[list[tuple[int, float]]], source: int) -> list[float]:
    n = min(len(adj_list), max(0, int(n_nodes)))
    if n == 0:
        return []
    src = max(0, min(n - 1, int(source)))
    inf = 1e12
    dist = [1e12] * n
    dist[src] = 0.0
    visited = [False] * n
    for _ in range(n):
        min_d = inf
        u = -1
        for i in range(n):
            if not visited[i] and dist[i] < min_d:
                min_d = dist[i]
                u = i
        if u == -1 or min_d >= inf:
            break
        visited[u] = True
        if u < len(adj_list):
            for edge in adj_list[u]:
                if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                    v = int(edge[0])
                    w = float(edge[1])
                    if 0 <= v < n and not visited[v]:
                        new_d = dist[u] + max(0.0, w)
                        if new_d < dist[v]:
                            dist[v] = new_d
    return dist

def bellman_ford_negative_detect(n_nodes: int, edges: list[tuple[int, int, float]], source: int) -> tuple[bool, list[float]]:
    n = max(0, int(n_nodes))
    if n == 0:
        return (False, [])
    src = max(0, min(n - 1, int(source)))
    inf = 1e12
    dist = [1e12] * n
    dist[src] = 0.0
    for _ in range(max(1, n - 1)):
        updated = False
        for u, v, w in edges:
            if 0 <= u < n and 0 <= v < n and dist[u] < inf:
                cand = dist[u] + float(w)
                if cand < dist[v]:
                    dist[v] = cand
                    updated = True
        if not updated:
            break
    has_neg_cycle = False
    for u, v, w in edges:
        if 0 <= u < n and 0 <= v < n and dist[u] < inf:
            if dist[u] + float(w) < dist[v] - 1e-9:
                has_neg_cycle = True
                break
    return (has_neg_cycle, dist)

def floyd_warshall_apsp_step(dist_matrix: list[list[float]], k: int, n: int) -> list[list[float]]:
    dim = max(0, int(n))
    if dim == 0 or len(dist_matrix) == 0:
        return []
    k_node = max(0, min(dim - 1, int(k)))
    inf = 1e12
    res = [[float(dist_matrix[i][j]) for j in range(dim)] for i in range(dim)]
    for i in range(dim):
        d_ik = res[i][k_node]
        if d_ik < inf:
            for j in range(dim):
                d_kj = res[k_node][j]
                if d_kj < inf:
                    cand = d_ik + d_kj
                    if cand < res[i][j]:
                        res[i][j] = cand
    return res

def johnson_reweighting_potentials(edges: list[tuple[int, int, float]], potentials: list[float]) -> list[tuple[int, int, float]]:
    n_pots = len(potentials)
    reweighted = []
    for edge in edges:
        if isinstance(edge, (list, tuple)) and len(edge) >= 3:
            u, v, w = int(edge[0]), int(edge[1]), float(edge[2])
        elif isinstance(edge, (int, float)):
            u, v, w = 0, 0, float(edge)
        else:
            continue
        hu = potentials[u] if 0 <= u < n_pots else 0.0
        hv = potentials[v] if 0 <= v < n_pots else 0.0
        w_hat = float(w) + float(hu) - float(hv)
        clamped_w = max(0.0, w_hat) if abs(w_hat) < 1e-12 else w_hat
        reweighted.append((int(u), int(v), float(clamped_w)))
    return reweighted

def a_star_heuristic_distance(current: int, target: int, g_cost: float, h_cost: float) -> float:
    g = max(0.0, float(g_cost))
    h = max(0.0, float(h_cost))
    if int(current) == int(target):
        return float(g)
    f = g + h
    return float(f)

def kruskal_minimum_spanning_tree(n_nodes: int, edges: list[tuple[int, int, float]]) -> tuple[float, list[tuple[int, int]]]:
    n = max(0, int(n_nodes))
    if n <= 1:
        return (0.0, [])
    parent = [i for i in range(n)]
    rank = [0] * n
    def find(i):
        curr = i
        while parent[curr] != curr:
            parent[curr] = parent[parent[curr]]
            curr = parent[curr]
        return curr
    sorted_edges = sorted(edges, key=lambda e: float(e[2]))
    total_weight = 0.0
    mst_edges = []
    for u, v, w in sorted_edges:
        if 0 <= u < n and 0 <= v < n:
            ru = find(u)
            rv = find(v)
            if ru != rv:
                total_weight += float(w)
                mst_edges.append((int(u), int(v)))
                if rank[ru] < rank[rv]:
                    parent[ru] = rv
                elif rank[ru] > rank[rv]:
                    parent[rv] = ru
                else:
                    parent[rv] = ru
                    rank[ru] += 1
                if len(mst_edges) == n - 1:
                    break
    return (float(total_weight), mst_edges)

def prim_minimum_spanning_tree(n_nodes: int, adj_list: list[list[tuple[int, float]]], start: int) -> tuple[float, list[tuple[int, int]]]:
    n = max(0, int(n_nodes))
    if n <= 1:
        return (0.0, [])
    src = max(0, min(n - 1, int(start)))
    inf = 1e12
    min_cost = [1e12] * n
    parent = [-1] * n
    in_mst = [False] * n
    min_cost[src] = 0.0
    total_weight = 0.0
    mst_edges = []
    for _ in range(n):
        u = -1
        best = inf
        for i in range(n):
            if not in_mst[i] and min_cost[i] < best:
                best = min_cost[i]
                u = i
        if u == -1 or best >= inf:
            break
        in_mst[u] = True
        total_weight += best
        if parent[u] != -1:
            mst_edges.append((parent[u], u))
        if u < len(adj_list):
            for v, w in adj_list[u]:
                if 0 <= v < n and not in_mst[v]:
                    cost = float(w)
                    if cost < min_cost[v]:
                        min_cost[v] = cost
                        parent[v] = u
    return (float(total_weight), mst_edges)

def tarjan_strongly_connected_components(n_nodes: int, adj_list: list[list[int]]) -> list[list[int]]:
    n = max(0, int(n_nodes))
    if n == 0:
        return []
    disc = [-1] * n
    low = [-1] * n
    on_stack = [False] * n
    stack = []
    timer = 0
    sccs = []
    for root in range(n):
        if disc[root] == -1:
            call_stack = [(root, 0)]
            while call_stack:
                u, edge_idx = call_stack[-1]
                if edge_idx == 0:
                    disc[u] = timer
                    low[u] = timer
                    timer += 1
                    stack.append(u)
                    on_stack[u] = True
                neighbors = adj_list[u] if u < len(adj_list) else []
                if edge_idx < len(neighbors):
                    v = neighbors[edge_idx]
                    call_stack[-1] = (u, edge_idx + 1)
                    if 0 <= v < n:
                        if disc[v] == -1:
                            call_stack.append((v, 0))
                        elif on_stack[v]:
                            if disc[v] < low[u]:
                                low[u] = disc[v]
                else:
                    call_stack.pop()
                    if call_stack:
                        p, _ = call_stack[-1]
                        if low[u] < low[p]:
                            low[p] = low[u]
                    if low[u] == disc[u]:
                        comp = []
                        while True:
                            w = stack.pop()
                            on_stack[w] = False
                            comp.append(w)
                            if w == u:
                                break
                        sccs.append(comp)
    return sccs

def kosaraju_scc_two_pass(n_nodes: int, adj_list: list[list[int]], rev_adj: list[list[int]]) -> list[list[int]]:
    n = max(0, int(n_nodes))
    if n == 0:
        return []
    visited = [False] * n
    order = []
    for i in range(n):
        if not visited[i]:
            st = [(i, 0)]
            visited[i] = True
            while st:
                u, idx = st[-1]
                nbrs = adj_list[u] if u < len(adj_list) else []
                if idx < len(nbrs):
                    v = nbrs[idx]
                    st[-1] = (u, idx + 1)
                    if 0 <= v < n and not visited[v]:
                        visited[v] = True
                        st.append((v, 0))
                else:
                    st.pop()
                    order.append(u)
    visited2 = [False] * n
    sccs = []
    for u in reversed(order):
        if not visited2[u]:
            comp = []
            q = [u]
            visited2[u] = True
            while q:
                curr = q.pop()
                comp.append(curr)
                rev_nbrs = rev_adj[curr] if curr < len(rev_adj) else []
                for v in rev_nbrs:
                    if 0 <= v < n and not visited2[v]:
                        visited2[v] = True
                        q.append(v)
            sccs.append(comp)
    return sccs

def topological_sort_kahn_indegree(n_nodes: int, adj_list: list[list[int]]) -> list[int]:
    n = max(0, int(n_nodes))
    if n == 0:
        return []
    in_deg = [0] * n
    for u in range(min(n, len(adj_list))):
        for v in adj_list[u]:
            if 0 <= v < n:
                in_deg[v] += 1
    queue = [i for i in range(n) if in_deg[i] == 0]
    order = []
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        order.append(u)
        if u < len(adj_list):
            for v in adj_list[u]:
                if 0 <= v < n:
                    in_deg[v] -= 1
                    if in_deg[v] == 0:
                        queue.append(v)
    if len(order) < n:
        return []
    return order

def cycle_detection_dfs_three_colors(n_nodes: int, adj_list: list[list[int]]) -> bool:
    n = max(0, int(n_nodes))
    if n <= 1:
        return False
    color = [0] * n
    for start in range(n):
        if color[start] == 0:
            stack = [(start, 0)]
            color[start] = 1
            while stack:
                u, idx = stack[-1]
                nbrs = adj_list[u] if u < len(adj_list) else []
                if idx < len(nbrs):
                    v = nbrs[idx]
                    stack[-1] = (u, idx + 1)
                    if 0 <= v < n:
                        if color[v] == 1:
                            return True
                        elif color[v] == 0:
                            color[v] = 1
                            stack.append((v, 0))
                else:
                    color[u] = 2
                    stack.pop()
    return False

def dinic_level_graph_max_flow(n_nodes: int, capacity: list[list[float]], source: int, sink: int) -> float:
    n = max(0, int(n_nodes))
    if n < 2:
        return 0.0
    src = max(0, min(n - 1, int(source)))
    dst = max(0, min(n - 1, int(sink)))
    if src == dst:
        return 0.0
    res = [[max(0.0, float(capacity[i][j])) for j in range(n)] for i in range(n)]
    total_flow = 0.0
    for _ in range(500):
        level = [-1] * n
        level[src] = 0
        q = [src]
        head = 0
        while head < len(q):
            u = q[head]
            head += 1
            for v in range(n):
                if level[v] == -1 and res[u][v] > 1e-9:
                    level[v] = level[u] + 1
                    q.append(v)
        if level[dst] == -1:
            break
        for _ in range(n * 2):
            st = [(src, 1e12, [src])]
            pushed_any = False
            while st:
                curr, f_in, path = st.pop()
                if curr == dst:
                    for idx in range(len(path) - 1):
                        p1 = path[idx]
                        p2 = path[idx + 1]
                        res[p1][p2] -= f_in
                        res[p2][p1] += f_in
                    total_flow += f_in
                    pushed_any = True
                    break
                for nxt in range(n):
                    if level[nxt] == level[curr] + 1 and res[curr][nxt] > 1e-9:
                        st.append((nxt, min(f_in, res[curr][nxt]), path + [nxt]))
            if not pushed_any:
                break
    return float(total_flow)

def hopcroft_karp_bipartite_matching(n_left: int, n_right: int, adj_left: list[list[int]]) -> int:
    nl = max(0, int(n_left))
    nr = max(0, int(n_right))
    if nl == 0 or nr == 0:
        return 0
    pair_v = [-1] * nr
    matching = 0
    for u in range(nl):
        visited = [False] * nr
        st = [u]
        parent = [-1] * nr
        found = -1
        while st and found == -1:
            curr = st.pop()
            nbrs = adj_left[curr] if curr < len(adj_left) else []
            for v in nbrs:
                if 0 <= v < nr and not visited[v]:
                    visited[v] = True
                    parent[v] = curr
                    if pair_v[v] == -1:
                        found = v
                        break
                    else:
                        st.append(pair_v[v])
        if found != -1:
            curr_v = found
            while curr_v != -1:
                prev_u = parent[curr_v]
                next_v = -1
                for v2 in range(nr):
                    if pair_v[v2] == prev_u:
                        next_v = v2
                        break
                pair_v[curr_v] = prev_u
                curr_v = next_v
            matching += 1
    return matching

def bipartite_graph_two_coloring(n_nodes: int, adj_list: list[list[int]]) -> tuple[bool, list[int]]:
    n = max(0, int(n_nodes))
    if n == 0:
        return (True, [])
    color = [-1] * n
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            q = [start]
            head = 0
            while head < len(q):
                u = q[head]
                head += 1
                nbrs = adj_list[u] if u < len(adj_list) else []
                for v in nbrs:
                    if 0 <= v < n:
                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            q.append(v)
                        elif color[v] == color[u]:
                            return (False, [])
    return (True, color)

def eulerian_circuit_hierholzer(n_nodes: int, adj_list: list[list[int]], start_node: int) -> list[int]:
    n = max(0, int(n_nodes))
    if n == 0:
        return []
    adj = [[v for v in (adj_list[i] if i < len(adj_list) else []) if 0 <= v < n] for i in range(n)]
    in_deg = [0] * n
    out_deg = [len(adj[i]) for i in range(n)]
    for u in range(n):
        for v in adj[u]:
            in_deg[v] += 1
    for i in range(n):
        if in_deg[i] != out_deg[i]:
            return []
    start = max(0, min(n - 1, int(start_node)))
    curr_path = [start]
    circuit = []
    while curr_path:
        curr = curr_path[-1]
        if adj[curr]:
            nxt = adj[curr].pop()
            curr_path.append(nxt)
        else:
            circuit.append(curr_path.pop())
    circuit.reverse()
    return circuit

def bridge_finding_tarjan_bridges(n_nodes: int, adj_list: list[list[int]]) -> list[tuple[int, int]]:
    n = max(0, int(n_nodes))
    if n <= 1:
        return []
    disc = [-1] * n
    low = [-1] * n
    bridges = []
    timer = 0
    for start in range(n):
        if disc[start] == -1:
            st = [(start, -1, 0)]
            while st:
                u, p, e_idx = st[-1]
                if e_idx == 0:
                    disc[u] = timer
                    low[u] = timer
                    timer += 1
                nbrs = adj_list[u] if u < len(adj_list) else []
                if e_idx < len(nbrs):
                    v = nbrs[e_idx]
                    st[-1] = (u, p, e_idx + 1)
                    if 0 <= v < n and v != p:
                        if disc[v] != -1:
                            if disc[v] < low[u]:
                                low[u] = disc[v]
                        else:
                            st.append((v, u, 0))
                else:
                    st.pop()
                    if st:
                        parent_u = st[-1][0]
                        if low[u] < low[parent_u]:
                            low[parent_u] = low[u]
                        if low[u] > disc[parent_u]:
                            edge = (min(parent_u, u), max(parent_u, u))
                            bridges.append(edge)
    return bridges

def articulation_points_cut_vertices(n_nodes: int, adj_list: list[list[int]]) -> list[int]:
    n = max(0, int(n_nodes))
    if n <= 2:
        return []
    disc = [-1] * n
    low = [-1] * n
    is_cut = [False] * n
    timer = 0
    for start in range(n):
        if disc[start] == -1:
            st = [(start, -1, 0, 0)]
            while st:
                u, p, e_idx, children = st[-1]
                if e_idx == 0:
                    disc[u] = timer
                    low[u] = timer
                    timer += 1
                nbrs = adj_list[u] if u < len(adj_list) else []
                if e_idx < len(nbrs):
                    v = nbrs[e_idx]
                    st[-1] = (u, p, e_idx + 1, children)
                    if 0 <= v < n and v != p:
                        if disc[v] != -1:
                            if disc[v] < low[u]:
                                low[u] = disc[v]
                        else:
                            st[-1] = (u, p, e_idx + 1, children + 1)
                            st.append((v, u, 0, 0))
                else:
                    curr_entry = st.pop()
                    c_count = curr_entry[3]
                    if p == -1:
                        if c_count >= 2:
                            is_cut[u] = True
                    else:
                        parent_u = st[-1][0]
                        if low[u] < low[parent_u]:
                            low[parent_u] = low[u]
                        if low[u] >= disc[parent_u]:
                            is_cut[parent_u] = True
    return [i for i in range(n) if is_cut[i]]

def graph_diameter_bfs_unweighted(n_nodes: int, adj_list: list[list[int]]) -> int:
    n = max(0, int(n_nodes))
    if n <= 1:
        return 0
    max_diam = 0
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        q = [start]
        head = 0
        while head < len(q):
            u = q[head]
            head += 1
            nbrs = adj_list[u] if u < len(adj_list) else []
            for v in nbrs:
                if 0 <= v < n and dist[v] == -1:
                    dist[v] = dist[u] + 1
                    if dist[v] > max_diam:
                        max_diam = dist[v]
                    q.append(v)
        if any(d == -1 for d in dist):
            return -1
    return int(max_diam)

def page_rank_power_iteration_step(adj_matrix: list[list[float]], p: list[float], damping: float) -> list[float]:
    n = len(p)
    if n == 0 or len(adj_matrix) != n:
        return []
    d = max(0.0, min(1.0, float(damping)))
    teleport = (1.0 - d) / float(n)
    out_p = [teleport for _ in range(n)]
    dangling_mass = 0.0
    for j in range(n):
        col_sum = sum(max(0.0, float(adj_matrix[i][j])) for i in range(n))
        if col_sum < 1e-12:
            dangling_mass += p[j]
        else:
            for i in range(n):
                w = max(0.0, float(adj_matrix[i][j])) / col_sum
                out_p[i] += d * w * p[j]
    dangling_contrib = (d * dangling_mass) / float(n)
    for i in range(n):
        out_p[i] += dangling_contrib
    total = sum(out_p)
    return [x / total for x in out_p] if total > 0.0 else [1.0 / float(n) for _ in range(n)]

def hits_authority_hub_update(adj_matrix: list[list[float]], auth: list[float], hub: list[float]) -> tuple[list[float], list[float]]:
    n = len(adj_matrix)
    if n == 0 or len(auth) != n or len(hub) != n:
        return ([], [])
    new_auth = [0.0] * n
    for i in range(n):
        new_auth[i] = sum(max(0.0, float(adj_matrix[j][i])) * max(0.0, float(hub[j])) for j in range(n))
    auth_norm = math.sqrt(sum(a * a for a in new_auth))
    if auth_norm > 1e-12:
        new_auth = [a / auth_norm for a in new_auth]
    else:
        new_auth = [1.0 / math.sqrt(float(n)) for _ in range(n)]
    new_hub = [0.0] * n
    for i in range(n):
        new_hub[i] = sum(max(0.0, float(adj_matrix[i][j])) * new_auth[j] for j in range(n))
    hub_norm = math.sqrt(sum(h * h for h in new_hub))
    if hub_norm > 1e-12:
        new_hub = [h / hub_norm for h in new_hub]
    else:
        new_hub = [1.0 / math.sqrt(float(n)) for _ in range(n)]
    return (new_auth, new_hub)

def graph_adjacency_laplacian_spectrum(n_nodes: int, adj_matrix: list[list[float]]) -> list[float]:
    n = len(adj_matrix) if len(adj_matrix) > 0 and len(adj_matrix) != int(n_nodes) else max(0, int(n_nodes))
    if n == 0 or len(adj_matrix) < n:
        return []
    deg_diag = [0.0] * n
    for i in range(n):
        d = 0.0
        row = adj_matrix[i]
        for j in range(min(n, len(row))):
            if i != j:
                d += max(0.0, float(row[j]))
        deg_diag[i] = d
    return deg_diag

def knapsack_01_dp_optimal_value(weights: list[int], values: list[float], capacity: int) -> float:
    cap = max(0, int(capacity))
    n = min(len(weights), len(values))
    if cap == 0 or n == 0:
        return 0.0
    dp = [0.0] * (cap + 1)
    for i in range(n):
        w = int(weights[i])
        v = float(values[i])
        if w > 0 and v > 0.0:
            for c in range(cap, w - 1, -1):
                cand = dp[c - w] + v
                if cand > dp[c]:
                    dp[c] = cand
    return float(dp[cap])

def knapsack_fractional_greedy(weights: list[float], values: list[float], capacity: float) -> float:
    rem_cap = max(0.0, float(capacity))
    n = min(len(weights), len(values))
    if rem_cap <= 0.0 or n == 0:
        return 0.0
    items = []
    for i in range(n):
        w = max(0.0, float(weights[i]))
        v = max(0.0, float(values[i]))
        if w > 1e-9:
            items.append((v / w, w, v))
    items.sort(key=lambda t: t[0], reverse=True)
    total_val = 0.0
    for ratio, w, v in items:
        if rem_cap <= 0.0:
            break
        take_w = min(w, rem_cap)
        total_val += take_w * ratio
        rem_cap -= take_w
    return float(total_val)

def longest_increasing_subsequence_patience(arr: list[int]) -> int:
    n = len(arr)
    if n <= 1:
        return n
    tails = []
    for x in arr:
        val = int(x)
        low = 0
        high = len(tails)
        while low < high:
            mid = (low + high) // 2
            if tails[mid] < val:
                low = mid + 1
            else:
                high = mid
        if low == len(tails):
            tails.append(val)
        else:
            tails[low] = val
    return len(tails)

def coin_change_minimum_coins_dp(coins: list[int], amount: int) -> int:
    target = int(amount)
    if target <= 0:
        return 0
    inf = 1000000
    dp = [1000000] * (target + 1)
    dp[0] = 0
    for c in coins:
        val = int(c)
        if val > 0:
            for a in range(val, target + 1):
                if dp[a - val] + 1 < dp[a]:
                    dp[a] = dp[a - val] + 1
    return dp[target] if dp[target] < inf else -1

def matrix_chain_multiplication_cost(p: list[int]) -> int:
    k_len = len(p)
    if k_len < 3:
        return 0
    n = k_len - 1
    inf = 1000000000
    m = [[0] * (n + 1) for _ in range(n + 1)]
    for l in range(2, n + 1):
        for i in range(1, n - l + 2):
            j = i + l - 1
            m[i][j] = inf
            for k in range(i, j):
                cost = m[i][k] + m[k + 1][j] + int(p[i - 1]) * int(p[k]) * int(p[j])
                if cost < m[i][j]:
                    m[i][j] = cost
    return int(m[1][n])

def rod_cutting_optimal_revenue(prices: list[float], length: int) -> float:
    target = max(0, int(length))
    if target == 0 or len(prices) == 0:
        return 0.0
    r = [0.0] * (target + 1)
    n_prices = len(prices)
    for j in range(1, target + 1):
        max_val = 0.0
        for i in range(min(j, n_prices)):
            cand = float(prices[i]) + r[j - 1 - i]
            if cand > max_val:
                max_val = cand
        r[j] = max_val
    return float(r[target])

def interval_scheduling_earliest_finish(intervals: list[tuple[float, float]]) -> list[tuple[float, float]]:
    valid = []
    for iv in intervals:
        if isinstance(iv, (list, tuple)) and len(iv) >= 2:
            s, e = float(iv[0]), float(iv[1])
            if s < e:
                valid.append((s, e))
        elif isinstance(iv, (int, float)):
            v = float(iv)
            if v > 0.0:
                valid.append((0.0, v))
    if not valid:
        return []
    sorted_ivs = sorted(valid, key=lambda iv: iv[1])
    selected = [sorted_ivs[0]]
    last_end = sorted_ivs[0][1]
    for idx in range(1, len(sorted_ivs)):
        s, e = sorted_ivs[idx]
        if s >= last_end:
            selected.append((s, e))
            last_end = e
    return selected

def weighted_interval_scheduling_dp(intervals: list[tuple[float, float, float]]) -> float:
    valid = [iv for iv in intervals if float(iv[0]) < float(iv[1]) and float(iv[2]) > 0.0]
    n = len(valid)
    if n == 0:
        return 0.0
    sorted_ivs = sorted(valid, key=lambda iv: float(iv[1]))
    dp = [0.0] * (n + 1)
    for i in range(1, n + 1):
        s_curr, _, w_curr = sorted_ivs[i - 1]
        low = 0
        high = i - 1
        p_idx = 0
        while low <= high:
            mid = (low + high) // 2
            if mid > 0 and float(sorted_ivs[mid - 1][1]) <= float(s_curr):
                p_idx = mid
                low = mid + 1
            else:
                high = mid - 1
        incl = float(w_curr) + dp[p_idx]
        excl = dp[i - 1]
        dp[i] = max(incl, excl)
    return float(dp[n])

def vertex_cover_2approx_greedy(edges: list[tuple[int, int]]) -> list[int]:
    if not edges:
        return []
    covered_nodes = set()
    for u, v in edges:
        u_idx = int(u)
        v_idx = int(v)
        if u_idx != v_idx:
            if u_idx not in covered_nodes and v_idx not in covered_nodes:
                covered_nodes.add(u_idx)
                covered_nodes.add(v_idx)
    return sorted(list(covered_nodes))

def set_cover_greedy_log_approx(universe: list[int], subsets: list[list[int]]) -> list[int]:
    uncovered = set(universe)
    if not uncovered or not subsets:
        return []
    sub_sets = [set(s) for s in subsets]
    chosen = []
    for _ in range(len(subsets)):
        best_idx = -1
        best_cov = 0
        for idx, s in enumerate(sub_sets):
            cov_count = len(s.intersection(uncovered))
            if cov_count > best_cov:
                best_cov = cov_count
                best_idx = idx
        if best_idx == -1 or best_cov == 0:
            break
        chosen.append(best_idx)
        uncovered.difference_update(sub_sets[best_idx])
        if not uncovered:
            break
    return chosen

def travelling_salesperson_nearest_neighbor(dist_matrix: list[list[float]], start_node: int) -> tuple[list[int], float]:
    n = len(dist_matrix)
    if n == 0:
        return ([], 0.0)
    start = max(0, min(n - 1, int(start_node)))
    visited = [False] * n
    visited[start] = True
    tour = [start]
    curr = start
    total_d = 0.0
    for _ in range(n - 1):
        best_d = 1e12
        nxt = -1
        for v in range(n):
            if not visited[v]:
                d = float(dist_matrix[curr][v])
                if d < best_d:
                    best_d = d
                    nxt = v
        if nxt == -1:
            break
        visited[nxt] = True
        tour.append(nxt)
        total_d += best_d
        curr = nxt
    total_d += float(dist_matrix[curr][start])
    tour.append(start)
    return (tour, float(total_d))

def graph_k_core_decomposition(n_nodes: int, adj_list: list[list[int]], k: int) -> list[int]:
    n = max(0, int(n_nodes))
    k_thresh = max(1, int(k))
    if n == 0:
        return []
    adj = [[v for v in (adj_list[i] if i < len(adj_list) else []) if 0 <= v < n and v != i] for i in range(n)]
    deg = [len(adj[i]) for i in range(n)]
    removed = [False] * n
    q = [i for i in range(n) if deg[i] < k_thresh]
    for u in q:
        removed[u] = True
    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        for v in adj[u]:
            if not removed[v]:
                deg[v] -= 1
                if deg[v] < k_thresh:
                    removed[v] = True
                    q.append(v)
    return [i for i in range(n) if not removed[i]]

def genetic_algorithm_tournament_select(fitness_scores: list[float], tournament_indices: list[int]) -> int:
    n = len(fitness_scores)
    if n == 0 or not tournament_indices:
        return 0
    best_idx = tournament_indices[0]
    best_fit = float(fitness_scores[best_idx]) if (0 <= best_idx < n) else -1e12
    for idx in tournament_indices[1:]:
        if 0 <= idx < n:
            fit = float(fitness_scores[idx])
            if fit > best_fit:
                best_fit = fit
                best_idx = idx
    return int(max(0, min(n - 1, best_idx)))

def genetic_algorithm_one_point_crossover(parent1: list[int], parent2: list[int], point: int) -> tuple[list[int], list[int]]:
    n = min(len(parent1), len(parent2))
    if n <= 1:
        return (list(parent1), list(parent2))
    pt = max(1, min(n - 1, int(point)))
    c1 = list(parent1[:pt]) + list(parent2[pt:n])
    c2 = list(parent2[:pt]) + list(parent1[pt:n])
    return (c1, c2)

def branch_and_bound_knapsack_bound(current_value: float, current_weight: float, capacity: float, items_left: list[tuple[float, float]]) -> float:
    cap = max(0.0, float(capacity))
    cur_w = float(current_weight)
    cur_v = float(current_value)
    if cur_w > cap:
        return 0.0
    bound = cur_v
    rem_cap = cap - cur_w
    sorted_items = sorted(items_left, key=lambda item: (float(item[0]) / max(1e-9, float(item[1]))), reverse=True)
    for v, w in sorted_items:
        val = max(0.0, float(v))
        weight = max(1e-9, float(w))
        if weight <= rem_cap:
            bound += val
            rem_cap -= weight
        else:
            bound += val * (rem_cap / weight)
            break
    return float(bound)

def stable_marriage_gale_shapley(proposer_prefs: list[list[int]], receiver_prefs: list[list[int]]) -> list[int]:
    n = min(len(proposer_prefs), len(receiver_prefs))
    if n == 0:
        return []
    match_receiver = [-1] * n
    prop_next = [0] * n
    free_proposers = [i for i in range(n)]
    rank_matrix = [[n for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for priority, p in enumerate(receiver_prefs[r]):
            if 0 <= p < n:
                rank_matrix[r][p] = priority
    while free_proposers:
        p = free_proposers.pop(0)
        if prop_next[p] < len(proposer_prefs[p]):
            r = proposer_prefs[p][prop_next[p]]
            prop_next[p] += 1
            if 0 <= r < n:
                curr_partner = match_receiver[r]
                if curr_partner == -1:
                    match_receiver[r] = p
                elif rank_matrix[r][p] < rank_matrix[r][curr_partner]:
                    match_receiver[r] = p
                    free_proposers.append(curr_partner)
                else:
                    free_proposers.append(p)
    return match_receiver
